// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    Log log_;

    function setUp() public {
        log_ = new Log();
        c = new MY_BANK(address(log_));
    }

    function testFuzz_property(uint96 amount, address actor, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(amount > 0);
        uint256 lenBefore = __logLength();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // General rule: after n successful Puts, History entry at index (n_before) exists —
        // i.e. every Put records exactly one log message.
        bool recorded = false;
        try log_.History(lenBefore) returns (address, string memory, uint, uint) {
            recorded = true;
        } catch {
            recorded = false;
        }
        assertTrue(recorded);
    }

    function __logLength() internal returns (uint256) {
        // Count History entries by probing indices upward (bounded loop).
        for (uint256 i = 0; i < 32; i++) {
            try log_.History(i) returns (address, string memory, uint, uint) {
                // entry exists, continue
            } catch {
                return i;
            }
        }
        revert("too many entries");
    }
}
